    private bool _isLoading = true;
    private bool _apiUnavailable;
    private bool _isStale;
    private bool _disposed;
    private SystemHealthReport? _healthReport;
    private SystemHealthReport? _cachedHealthReport;
    private DateTimeOffset _lastRefreshUtc;

    private string _staleBannerTitle => $"Health data may be stale \u2014 last updated {FormatTimeAgo(_lastRefreshUtc)}";

    protected override async Task OnInitializedAsync()
    {
        RefreshService.OnDataChanged += OnRefreshSignal;
        RefreshService.OnError += OnRefreshError;

        try
        {
            SystemHealthReport? health = await ApiClient.GetSystemHealthAsync();
            if (health is not null)
            {
                _healthReport = health;
                _cachedHealthReport = health;
                _apiUnavailable = false;
                _isStale = false;
                _lastRefreshUtc = DateTimeOffset.UtcNow;
            }
            else
            {
                _apiUnavailable = true;
            }
        }
        catch (Exception)
        {
            _apiUnavailable = true;
        }
        finally
        {
            _isLoading = false;
        }
    }

    private void OnRefreshSignal(DashboardData data)
    {
        if (_disposed)
        {
            return;
        }

        _ = InvokeAsync(() =>
        {
            try
            {
                if (data.Health is not null)
                {
                    _healthReport = data.Health;
                    _cachedHealthReport = data.Health;
                    _isStale = false;
                    _apiUnavailable = false;
                    _lastRefreshUtc = DateTimeOffset.UtcNow;
                }
                else
                {
                    _isStale = _cachedHealthReport is not null;
                    _apiUnavailable = _cachedHealthReport is null;
                }

                StateHasChanged();
            }
            catch (ObjectDisposedException)
            {
            }
        });
    }

    private void OnRefreshError(Exception exception)
    {
        if (_disposed)
        {
            return;
        }

        _ = InvokeAsync(() =>
        {
            try
            {
                if (IsAuthContextFailure(exception))
                {
                    _cachedHealthReport = null;
                    _healthReport = null;
                    _isStale = false;
                    _apiUnavailable = true;
                }
                else
                {
                    _isStale = _cachedHealthReport is not null;
                    _apiUnavailable = _cachedHealthReport is null;
                }

                // Round 10 P4: refresh failures must clear the loading state. After a successful
                // initial load + a manual Retry that sets _isLoading = true, a refresh failure
                // would otherwise leave the skeleton card visible alongside the issue banner —
                // the page looks stuck in loading instead of presenting the failure outcome.
                _isLoading = false;
                StateHasChanged();
            }
            catch (ObjectDisposedException)
            {
            }
        });
    }

    private async Task LoadDataAsync()
    {
        // Set _isLoading so the SkeletonCard reappears during a Retry attempt; otherwise the page
        // looks frozen while the API call is in flight after a previous failure (AC2 spec line 98:
        // "the Refresh button returns to an idle state after success or failure" implies the
        // intermediate state is observable).
        _isLoading = true;
        try
        {
            SystemHealthReport? health = await ApiClient.GetSystemHealthAsync();
            if (health is not null)
            {
                _healthReport = health;
                _cachedHealthReport = health;
                _apiUnavailable = false;
                _isStale = false;
                _lastRefreshUtc = DateTimeOffset.UtcNow;
            }
            else
            {
                _isStale = _cachedHealthReport is not null;
                _apiUnavailable = _cachedHealthReport is null;
            }
        }
        catch (Exception ex)
        {
            if (IsAuthContextFailure(ex))
            {
                _cachedHealthReport = null;
                _healthReport = null;
                _isStale = false;
                _apiUnavailable = true;
            }
            else
            {
                _isStale = _cachedHealthReport is not null;
                _apiUnavailable = _cachedHealthReport is null;
            }
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task OnManualRefresh()
    {
        await RefreshService.TriggerImmediateRefreshAsync();
    }

    public ValueTask DisposeAsync()
    {
        RefreshService.OnDataChanged -= OnRefreshSignal;
        RefreshService.OnError -= OnRefreshError;
        _disposed = true;
        return ValueTask.CompletedTask;
    }

    // ADR-3 Truthful Metrics shared with Index.razor:
    //   - Available    -> render the real measurement (zero is honest if measured zero)
    //   - Unavailable  -> render "unavailable" (never 0, 0.0/s, or 0.0%)
    //   - Stale        -> render the stale value with a "(stale)" suffix
    private static string FormatTotalEvents(SystemHealthReport report, bool isStale) => report.TotalEventCountStatus switch
    {
        SystemHealthMetricStatus.Unavailable => "unavailable",
        SystemHealthMetricStatus.Stale => $"{report.TotalEventCount:N0} (stale)",
        _ => isStale ? $"{report.TotalEventCount:N0} (stale)" : report.TotalEventCount.ToString("N0"),
    };

    private static string FormatEventsPerSecond(SystemHealthReport report, bool isStale) => report.EventsPerSecondStatus switch
    {
        SystemHealthMetricStatus.Unavailable => "unavailable",
        SystemHealthMetricStatus.Stale => $"{report.EventsPerSecond:F1} (stale)",
        _ => isStale ? $"{report.EventsPerSecond:F1} (stale)" : report.EventsPerSecond.ToString("F1"),
    };

    private static string FormatErrorRate(SystemHealthReport report, bool isStale) => report.ErrorPercentageStatus switch
    {
        SystemHealthMetricStatus.Unavailable => "unavailable",
        SystemHealthMetricStatus.Stale => $"{report.ErrorPercentage:F1}% (stale)",
        _ => isStale ? $"{report.ErrorPercentage:F1}% (stale)" : $"{report.ErrorPercentage:F1}%",
    };

    // Severity must visually distinguish Unavailable from Available so an operator scanning the
    // dashboard cannot confuse a healthy zero with an unknown-zero. For metrics with a
    // value-based gradient (Events/sec, Error Rate) the call site uses IsValueShown to bypass
    // this method and pick the gradient-derived severity for both Available AND Stale: a stale
    // 50% error rate must still render as "error", not flatten to "warning". Total Events has
    // no gradient so this method's "neutral" arm applies for Available/Stale.
    private string MetricSeverity(SystemHealthMetricStatus status) => status switch
    {
        SystemHealthMetricStatus.Available => "neutral",
        SystemHealthMetricStatus.Stale => "neutral",
        SystemHealthMetricStatus.Unavailable => "warning",
        _ => LogUnknownMetricSeverity(status),
    };

    private string LogUnknownMetricSeverity(SystemHealthMetricStatus status)
    {
        Logger.LogWarning("Unrecognised SystemHealthMetricStatus '{Status}' in Health page severity mapping.", status);
        return "warning";
    }

    // True when a value should be rendered to the user (Available or Stale). Drives the choice
    // between value-gradient severity and status-derived severity.
    private static bool IsValueShown(SystemHealthMetricStatus status)
        => status is SystemHealthMetricStatus.Available or SystemHealthMetricStatus.Stale;

    private static string GetEventsPerSecondSeverity(double value)
        => value > 0 ? "success" : "neutral";

    private static string GetHealthSeverity(HealthStatus status) => status switch
    {
        HealthStatus.Healthy => "success",
        HealthStatus.Degraded => "warning",
        HealthStatus.Unhealthy => "error",
        _ => "neutral",
    };

    private static string FormatSource(DaprComponentSource source) => source switch
    {
        DaprComponentSource.RemoteEventStoreMetadata => "Remote (eventstore)",
        DaprComponentSource.LocalAdminProbe => "Local probe",
        DaprComponentSource.LocalAdminMetadataFallback => "Local fallback",
        DaprComponentSource.Unavailable => "unavailable",
        _ => $"unknown ({source})",
    };

    // Round 5 P9: build outage-cause description for the empty-inventory empty-state when
    // OverallStatus is Unhealthy. Operators see the canonical metadata-source statuses
    // explicitly rather than a friendly "no components yet" message that hides the cause.
    private static string BuildEmptyInventoryOutageDescription(SystemHealthReport report)
    {
        List<string> causes = [];
        if (report.LocalSidecarMetadataStatus != RemoteMetadataStatus.Available)
        {
            causes.Add($"the local Admin sidecar metadata is {FormatRemoteMetadataStatus(report.LocalSidecarMetadataStatus)}");
        }

        if (report.InventorySourceStatus != RemoteMetadataStatus.Available
            && report.InventorySourceStatus != RemoteMetadataStatus.NotConfigured)
        {
            causes.Add($"the remote EventStore sidecar metadata is {FormatRemoteMetadataStatus(report.InventorySourceStatus)}");
        }

        return causes.Count switch
        {
            0 => "No DAPR components were reported. The configured state store may be misconfigured; see logs for the AdminServerOptions.StateStoreName diagnostic warning.",
            1 => $"DAPR component inventory is unavailable because {causes[0]}. Live health and DAPR pages will refresh once the metadata source recovers.",
            _ => $"DAPR component inventory is unavailable because {string.Join(" and ", causes)}. Live health and DAPR pages will refresh once the metadata sources recover.",
        };
    }

    private static string FormatRemoteMetadataStatus(RemoteMetadataStatus status) => status switch
    {
        RemoteMetadataStatus.Available => "available",
        RemoteMetadataStatus.NotConfigured => "not configured",
        RemoteMetadataStatus.Unreachable => "unreachable",
        RemoteMetadataStatus.InvalidPayload => "invalid (payload could not be parsed)",
        _ => $"unknown ({status})",
    };

    private static string GetSourceTitle(DaprComponentSource source) => source switch
    {
        DaprComponentSource.RemoteEventStoreMetadata => "Inventory reported by the remote EventStore sidecar metadata; status may include local probe evidence for the configured state store.",
        DaprComponentSource.LocalAdminProbe => "Confirmed by an Admin.Server local dependency probe.",
        DaprComponentSource.LocalAdminMetadataFallback => "Sourced from local Admin sidecar metadata as a degraded fallback only.",
        DaprComponentSource.Unavailable => "Source attribution unavailable for this fact.",
        _ => $"Unrecognized DaprComponentSource value '{source}' — UI translation missing.",
    };

    private static string GetHealthEvidenceTitle(DaprComponentSource source) => source switch
    {
        DaprComponentSource.RemoteEventStoreMetadata => "Status evidence came from remote EventStore sidecar metadata.",
        DaprComponentSource.LocalAdminProbe => "Status evidence came from an Admin.Server local dependency probe.",
        DaprComponentSource.LocalAdminMetadataFallback => "Status evidence came from local Admin sidecar metadata fallback.",
        DaprComponentSource.Unavailable => "Health evidence source unavailable for this status.",
        _ => $"Unrecognized DaprComponentSource value '{source}' — UI translation missing.",
    };

    // Round 10 P0a (auth-user half): cache invalidation on auth-user change is signalled here
    // via 401/403 from the API. Any subsequent request issued under a different identity (after
    // logout/relogin/role change) sees this rejection and clears `_cachedHealthReport`,
    // preventing prior-user data from rendering as stale. The tenant-context half of the
    // round-9 finding is a no-op for this page: `/health` is system-wide (per Round 1 deferral
    // rationale "Health is system-wide so cross-tenant stale-data reuse is not in scope") — it
    // does NOT render tenant-scoped data, so a tenant-id change in another component does not
    // make any displayed value stale. Adding a tenant-changed subscription here would invalidate
    // the cache after every tenant-filter click on other pages with no operator benefit.
    private static bool IsAuthContextFailure(Exception exception)
        => exception is UnauthorizedAccessException
            or ForbiddenAccessException
            or AdminApiProblemException { StatusCode: System.Net.HttpStatusCode.Unauthorized or System.Net.HttpStatusCode.Forbidden };

    private static string GetErrorRateSeverity(double percentage)
    {
        if (percentage < 1.0)
        {
            return "success";
        }

        return percentage < 5.0 ? "warning" : "error";
    }

    private static string GetDaprComponentsSeverity(IEnumerable<DaprComponentHealth> components)
    {
        if (components.Any(c => c.Status == HealthStatus.Unhealthy))
        {
            return "error";
        }

        if (components.Any(c => c.Status == HealthStatus.Degraded))
        {
            return "warning";
        }

        return "success";
    }

    private static string GetOverallStatusColor(HealthStatus status) => status switch
    {
        HealthStatus.Healthy => "var(--hexalith-status-success)",
        HealthStatus.Degraded => "var(--hexalith-status-warning)",
        HealthStatus.Unhealthy => "var(--hexalith-status-error)",
        _ => "var(--hexalith-status-neutral)",
    };

    private static string GetOverallStatusIcon(HealthStatus status) => status switch
    {
        HealthStatus.Healthy => "\u2714",
        HealthStatus.Degraded => "\u26A0",
        HealthStatus.Unhealthy => "\u2716",
        _ => "\u2022",
    };

    private static bool HasAnyObservabilityUrl(ObservabilityLinks links) =>
        IsValidHttpUrl(links.TraceUrl)
        || IsValidHttpUrl(links.MetricsUrl)
        || IsValidHttpUrl(links.LogsUrl);

    private static bool IsValidHttpUrl(string? url) =>
        !string.IsNullOrEmpty(url)
        && Uri.TryCreate(url, UriKind.Absolute, out Uri? uri)
        && (uri.Scheme == "http" || uri.Scheme == "https");

    private static string FormatTimeAgo(DateTimeOffset timestamp)
    {
        if (timestamp == default)
        {
            return "Never";
        }

        TimeSpan elapsed = DateTimeOffset.UtcNow - timestamp;
        if (elapsed < TimeSpan.Zero)
        {
            return "just now";
        }

        if (elapsed.TotalSeconds < 60)
        {
            return "just now";
        }

        if (elapsed.TotalMinutes < 60)
        {
            int minutes = (int)elapsed.TotalMinutes;
            return $"{minutes} {(minutes == 1 ? "min" : "min")} ago";
        }

        if (elapsed.TotalHours < 24)
        {
            int hours = (int)elapsed.TotalHours;
            return $"{hours} {(hours == 1 ? "hour" : "hours")} ago";
        }

        return timestamp.ToString("yyyy-MM-dd");
    }

